const { property, operation, value } = filter;

if (!property || !operation) return null;

// Handle "Is Null" / "Is Not Null" (No value needed)
const noValueOps = ['isnull', 'isnotnull'];
if (noValueOps.includes(operation.toLowerCase())) {
    return `${property}_${operation}`;
}

// Validate value existence
if (value === undefined || value === null || value === "") return null;

// Encode value safely
return `${property}_${operation}=${encodeURIComponent(value)}`;

