// 1. Check User Preference (High Priority)
const userPref = userPreferenceService.get('quickSearch', entityType);
if (userPref) {
    return userPref;
}

// 2. Use Passed Defaults (Medium Priority)
// The controller passes this object, so this service stays generic
if (defaultSettings) {
    return defaultSettings;
}

// 3. Fallback (Low Priority)
return {
    property: "Keywords",
    operation: "contains",
    label: "Keywords"
};

