try {
    const config = this.quickSearchConfig.get(entityType, defaultSettings, userPreferenceService);
    const { property, operation } = config;

    if (!property || !operation) {
        return '';
    }

    const noValueOperations = ['isnull', 'isnotnull'];

    if (noValueOperations.includes(operation)) {
        return `${property}_${operation}`;
    }

    if (!value) {
        return '';
    }

    return `${property}_${operation}=${value}`;

} catch (error) {
    console.error('Error constructing query string:', error);
    return null;
}

const { quickSearchConfig, quickSearchValue, advancedFilters = [] } = params;
const queryParts = [];

// 1. Handle Quick Search (if active)
if (quickSearchValue && quickSearchValue.trim() !== "") {
    const qsPart = this._buildSingleQueryPart({
        property: quickSearchConfig.property,
        operation: quickSearchConfig.operation,
        value: quickSearchValue
    });
    if (qsPart) queryParts.push(qsPart);
}

// 2. Handle Advanced Filters
advancedFilters.forEach(filter => {
    const part = this._buildSingleQueryPart(filter);
    if (part) queryParts.push(part);
});

// 3. Join with '&'
return queryParts.join("&");

if (!filters || !Array.isArray(filters)) return { strings: [], map: {} };

const strings = [];
const map = {};
const processedDefinitions = definitions.map(d => ({
    ...d,
    property: d.value
}));

filters.forEach(filter => {
    const def = processedDefinitions.find(d => d.property === filter.property);
    if (!def) return;

    const label = def.label || filter.property;
    const op = opMap[filter.operation] || filter.operation;

    let displayValue = filter.value;

    if (def.type === 'dropdown' && def.source && referenceData[def.source]) {
        const list = referenceData[def.source];
        const match = list.find(item => String(item.value) === String(filter.value));
        if (match) {
            displayValue = match.label;
        }
    } else if (def.type === "boolean") {
        displayValue = filter.value === "1" ? "YES" : "NO"
    }

    const displayText = ['isnull', 'isnotnull'].includes(filter.operation)
        ? `${label} ${op}`
        : `${label} ${op} "${displayValue}"`;

    strings.push(displayText);
    map[displayText] = filter;
});

return { strings, map };
